import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv3d_cute_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride, int padding, int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled 3D convolution kernel using CuTe tensors.
// Strategy:
//  - Each CTA (block) handles one batch element (n) and a tile of `PosTile`
//    output spatial positions.
//  - The full weight tensor is cached in shared memory once at kernel start
//    (small: Cout * Cin_per_group * K^3 floats).
//  - For each group, an im2col-style patch (PosTile x R, R=Cin_per_group*K^3)
//    is cooperatively gathered into shared memory (with zero-padding logic),
//    then every thread computes a (position, out-channel) dot-product pair
//    against the cached weights.
//  - This avoids re-reading the same input patch from global memory once per
//    output channel (the naive approach), turning it into a small local
//    "GEMM-like" reduction entirely out of shared memory.

template <typename T>
__global__ void conv3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ Wt,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int K,
    int stride, int padding, int dilation,
    int groups,
    int Dout, int Hout, int Wout)
{
  constexpr int Threads = 256;
  constexpr int PosTile = 32;

  const int tid = threadIdx.x;
  const int n = blockIdx.y;

  const int Cin_per_group  = Cin / groups;
  const int Cout_per_group = Cout / groups;
  const int KK   = K * K;
  const int KKK  = K * K * K;
  const int R    = Cin_per_group * KKK;      // reduction length per group
  const int Wsize = Cout * R;                // total weight elements

  extern __shared__ float smem[];
  float* sW     = smem;             // Wsize floats
  float* sPatch = smem + Wsize;     // PosTile * R floats

  __shared__ int  od_s[PosTile];
  __shared__ int  oh_s[PosTile];
  __shared__ int  ow_s[PosTile];
  __shared__ bool valid_s[PosTile];

  const int P_total = Dout * Hout * Wout;
  const int p_block = blockIdx.x * PosTile;

  // Load full weight tensor into shared memory (reused across all groups).
  for (int i = tid; i < Wsize; i += Threads) {
    sW[i] = (float)Wt[i];
  }

  // Compute output coordinates for each position in this tile.
  for (int pos = tid; pos < PosTile; pos += Threads) {
    int p = p_block + pos;
    if (p < P_total) {
      int od = p / (Hout * Wout);
      int rem = p - od * Hout * Wout;
      int oh = rem / Wout;
      int ow = rem - oh * Wout;
      od_s[pos] = od;
      oh_s[pos] = oh;
      ow_s[pos] = ow;
      valid_s[pos] = true;
    } else {
      valid_s[pos] = false;
    }
  }
  __syncthreads();

  // Strides (contiguous NCDHW layout)
  const int64_t sXn = (int64_t)Cin * D * H * Win;
  const int64_t sXc = (int64_t)D * H * Win;
  const int64_t sXd = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, D, H, Win),
      make_stride(sXc, sXd, sXh, Int<1>{}));

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{}));

  for (int g = 0; g < groups; ++g) {
    const int ci_base = g * Cin_per_group;
    const int co_base = g * Cout_per_group;

    // Gather input patch for this group into shared memory.
    const int totalLoad = PosTile * R;
    for (int idx = tid; idx < totalLoad; idx += Threads) {
      int pos = idx / R;
      int r   = idx % R;
      float xval = 0.0f;

      if (valid_s[pos]) {
        int ci_local = r / KKK;
        int rem      = r % KKK;
        int kd = rem / KK;
        int rem2 = rem % KK;
        int kh = rem2 / K;
        int kw = rem2 % K;

        int od = od_s[pos];
        int oh = oh_s[pos];
        int ow = ow_s[pos];

        int id = od * stride - padding + kd * dilation;
        int ih = oh * stride - padding + kh * dilation;
        int iw = ow * stride - padding + kw * dilation;

        if (id >= 0 && id < D && ih >= 0 && ih < H && iw >= 0 && iw < Win) {
          int ci = ci_base + ci_local;
          xval = (float)mX(ci, id, ih, iw);
        }
      }
      sPatch[idx] = xval;
    }
    __syncthreads();

    // Compute outputs for this group's channels using register blocking:
    // each thread accumulates COUT_BLOCK output channels simultaneously for
    // the same output position, reusing each loaded patch element across
    // multiple output-channel accumulations (reduces shared-memory reads).
    // Compute outputs for this group's channels using 2D register blocking:
    // each thread accumulates a POS_BLOCK x COUT_BLOCK tile of outputs,
    // reusing each loaded patch element across COUT_BLOCK output channels
    // and each loaded weight element across POS_BLOCK output positions.
    constexpr int COUT_BLOCK = 4;
    constexpr int POS_BLOCK = 2;
    const int coGroups  = (Cout_per_group + COUT_BLOCK - 1) / COUT_BLOCK;
    const int posGroups = (PosTile + POS_BLOCK - 1) / POS_BLOCK;
    const int total_units = posGroups * coGroups;
    for (int idx = tid; idx < total_units; idx += Threads) {
      int posGroupIdx = idx / coGroups;
      int coGroupIdx  = idx % coGroups;
      const int pos_base = posGroupIdx * POS_BLOCK;
      const int co_local_base = coGroupIdx * COUT_BLOCK;
      float acc[POS_BLOCK][COUT_BLOCK];
      #pragma unroll
      for (int pi = 0; pi < POS_BLOCK; ++pi) {
        #pragma unroll
        for (int j = 0; j < COUT_BLOCK; ++j) {
          int co_local = co_local_base + j;
          acc[pi][j] = 0.0f;
          if (co_local < Cout_per_group && Bias != nullptr) {
            acc[pi][j] = (float)Bias[co_base + co_local];
          }
        }
      }
      const float* wRowBase = sW + co_base * R + co_local_base * R;
      #pragma unroll 4
      for (int r = 0; r < R; ++r) {
        float pval[POS_BLOCK];
        #pragma unroll
        for (int pi = 0; pi < POS_BLOCK; ++pi) {
          int pos = pos_base + pi;
          pval[pi] = (pos < PosTile && valid_s[pos]) ? sPatch[pos * R + r] : 0.0f;
        }
        float wval[COUT_BLOCK];
        #pragma unroll
        for (int j = 0; j < COUT_BLOCK; ++j) {
          int co_local = co_local_base + j;
          wval[j] = (co_local < Cout_per_group) ? wRowBase[j * R + r] : 0.0f;
        }
        #pragma unroll
        for (int pi = 0; pi < POS_BLOCK; ++pi) {
          #pragma unroll
          for (int j = 0; j < COUT_BLOCK; ++j) {
            acc[pi][j] += pval[pi] * wval[j];
          }
        }
      }
      #pragma unroll
      for (int pi = 0; pi < POS_BLOCK; ++pi) {
        int pos = pos_base + pi;
        if (pos >= PosTile || !valid_s[pos]) continue;
        #pragma unroll
        for (int j = 0; j < COUT_BLOCK; ++j) {
          int co_local = co_local_base + j;
          if (co_local < Cout_per_group) {
            int co = co_base + co_local;
            mY(co, od_s[pos], oh_s[pos], ow_s[pos]) = static_cast<T>(acc[pi][j]);
          }
        }
      }
    }
    __syncthreads();
  }
}

torch::Tensor conv3d_cute_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride, int padding, int dilation, int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 5, "x must be [N, Cin, D, H, W]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cout, Cin/groups, K, K, K]");

  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t D   = x.size(2);
  int64_t H   = x.size(3);
  int64_t Win = x.size(4);

  int64_t Cout = w.size(0);
  int64_t Cin_per_group = w.size(1);
  int64_t K = w.size(2);
  TORCH_CHECK(w.size(3) == K && w.size(4) == K, "kernel must be cubic (K,K,K)");
  TORCH_CHECK(groups > 0, "groups must be > 0");
  TORCH_CHECK(Cin % groups == 0 && Cout % groups == 0, "Cin/Cout must be divisible by groups");
  TORCH_CHECK(Cin_per_group == Cin / groups, "weight Cin dim mismatch with groups");

  TORCH_CHECK(stride > 0 && dilation > 0, "stride/dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t Dout = (D + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Hout = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());

  constexpr int Threads = 256;
  constexpr int PosTile = 32;

  int64_t Cout_per_group = Cout / groups;
  int64_t R = Cin_per_group * K * K * K;
  int64_t Wsize = Cout * R;
  int64_t PatchSize = (int64_t)PosTile * R;
  size_t shmemBytes = (size_t)(Wsize + PatchSize) * sizeof(float);

  if (shmemBytes > 48 * 1024) {
    cudaFuncSetAttribute(conv3d_kernel<float>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)shmemBytes);
  }

  int64_t P_total = Dout * Hout * Wout;
  dim3 block(Threads);
  dim3 grid((unsigned)((P_total + PosTile - 1) / PosTile), (unsigned)N, 1);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv3d_kernel<float><<<grid, block, shmemBytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)D, (int)H, (int)Win,
      (int)Cout, (int)K,
      stride, padding, dilation, groups,
      (int)Dout, (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv3d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv3d_ext = load_inline(
    name="cute_conv3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv3d_cute_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 3D convolution (square kernel) implemented with a single custom
    CUDA kernel written using CuTe tensors/layouts. The kernel caches the
    (small) weight tensor and per-tile im2col patches in shared memory,
    turning the per-output-pixel work into a shared-memory dot product
    instead of repeatedly re-reading global memory per output channel.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 groups: int = 1,
                 bias: bool = False) -> None:
        super().__init__()
        assert isinstance(kernel_size, int)
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        Cout = self.out_channels
        Cin_per_group = self.in_channels // self.groups
        K = self.kernel_size

        self.weight = nn.Parameter(torch.empty(Cout, Cin_per_group, K, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(Cout))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3) * self.weight.size(4)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv3d_cute_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            self.stride,
            self.padding,
            self.dilation,
            self.groups,
        )

