  TORCH_CHECK(w.dim() == 5, "w must be [Cout, Cin/groups, K, K, K]");

  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t D   = x.size(2);
  int64_t H   = x.size(3);
  int64_t Win = x.size(4);

  int64_t Cout = w.size(0);
  int64_t Cin_per_group = w.size(1);
  int64_t K = w.size(2);
  TORCH_CHECK(w.size(3) == K && w.size(4) == K, "kernel must be cubic (K,K,K)");
  TORCH_CHECK(groups > 0, "groups must be > 0");
  TORCH_CHECK(Cin % groups == 0 && Cout % groups == 0, "Cin/Cout must be divisible by groups");
  TORCH_CHECK(Cin_per_group == Cin / groups, "weight Cin dim mismatch with groups");

